package com.dentalclinic.patientcare.entity;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.*;
@Entity @Table(name="patient_consent_records") public class ConsentRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull private Long patientId; @NotBlank @Size(max=120) private String consentType; @NotNull private Boolean consented; @NotNull private LocalDate consentDate; @Size(max=120) private String recordedBy; @Size(max=500) private String notes;
public Long getId(){return id;}public void setId(Long v){id=v;}public Long getPatientId(){return patientId;}public void setPatientId(Long v){patientId=v;}public String getConsentType(){return consentType;}public void setConsentType(String v){consentType=v;}public Boolean getConsented(){return consented;}public void setConsented(Boolean v){consented=v;}public LocalDate getConsentDate(){return consentDate;}public void setConsentDate(LocalDate v){consentDate=v;}public String getRecordedBy(){return recordedBy;}public void setRecordedBy(String v){recordedBy=v;}public String getNotes(){return notes;}public void setNotes(String v){notes=v;}}
